{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 public access block is not configured",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The log bucket has no account-level bucket control preventing public ACLs or bucket policies. A future policy or ACL change could therefore expose sensitive log data publicly."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 lifecycle configuration is missing",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle rule to manage abandoned multipart uploads. Unfinished uploads can accumulate indefinitely and consume storage."
    },
    {
      "check_id": "CKV2_AWS_62",
      "title": "S3 event notifications are not enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Object-level events for this log bucket are not published to an event service, reducing visibility into changes to security-relevant log data."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Log bucket permits forced destruction",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The bucket sets force_destroy to true, allowing Terraform to delete the bucket and all retained log versions. This increases the impact of an accidental or malicious infrastructure deletion."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }

  lifecycle_rule {
    id                                     = "abort-incomplete-multipart-uploads"
    enabled                                = true
    abort_incomplete_multipart_upload_days = 7
  }

  force_destroy = false

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
    }, {
  })
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_notification" "logs" {
  bucket      = aws_s3_bucket.logs.id
  eventbridge = true
}
",
  "fix_summary": "Added an S3 public access block, enabled EventBridge object-event notifications, and added lifecycle cleanup for incomplete multipart uploads. Disabled forced destruction to protect retained log data; access logging and cross-region replication were not added because this is itself a log-delivery bucket and no separate logging or regional replication destination is defined."
}
